# The final recovery grasp failed and the third tube remains loose on the rack.
# Withdraw with open fingers and return both arms to their saved home joints within the remaining budget.
clear_pose = list(get_observation()['state']['right_ee_pose'])
obs, ended, truncated = ee_move('right', clear_pose, 1.0, max_steps=3, min_steps=3)
if not ended and not truncated:
    for i in range(20):
        action = {'left_arm_joint_state': home_left, 'right_arm_joint_state': home_right, 'left_ee_joint_state': [1.0], 'right_ee_joint_state': [1.0]}
        obs, reward, ended, truncated, info = step(action)
        if ended or truncated:
            break
    print('home steps', i+1, 'reward', reward, 'ended', ended, truncated, 'info', info)

